using Orpheus.Net.Protocol;

namespace Orpheus.Net
{
    /// <summary>
    /// Модуль сети (docs/07, 2.10): протокол, снимки, часы, <c>ITransport</c> (LiteNetLib, связь в памяти, имитатор).
    /// </summary>
    public static class NetModule
    {
        /// <summary>Версия протокола: растёт с каждым несовместимым изменением схемы сообщений.</summary>
        public const int ProtocolVersion = 38; // 38 — владелец личной капли в куче (NetPile.Owner u32, +4 байта на кучу; E3-3b); 37 — действие персонажа в снимке (8 бит: инструмент — кирка/лук + прогресс 6 бит, маска дельты 7 бит; C-036); 36 — пачка событий боя (тип 40: урон/снаряд/взмах записями) + лимит куч на такт (C-035); 2 — хэш генерации во «входе принят» (0-017); 3 — токен хозяина во входе, «Открыть для друзей», «мир закрывается» (0-024); 4 — эпоха часов в снимке и дельте, Ping/Pong (0-025); 5 — мир по сети: чанк, пачка правок, центр окна, запрос чанка (0-026); 6 — уворот в своём состоянии снимка, «замах начат» (13) и «удар решён» (14) (0-029); 7 — запрос правки (20) и ответ на неё (21) (0-028); 8 — опережение L в вводе (0…24), отчёт «запас прихода кадров» и D_p в своём состоянии снимка, D_p получателя в «замах начат» (0-033); 9 — отказ входа «имя занято» (0-035); 10 — пауза: запрос (22) и состояние (23) (0-036); 11 — бой: здоровье/масса/отбрасывание в своём состоянии, доля здоровья сущности в снимке (7 бит, маска дельты), урон в «ударе решён», смерть (24) и возрождение (25) (1-001); 12 — кадр ввода: угол прицела и ячейка быстрой панели (InputFrame 6 байт — журнал формата 2, WireFrame 7 байт, InputMessage 42 байта) (1-002); 13 — сумка (26): предмет в руках сущности в снимке (8 бит, маска дельты 4 бита) и сумка владельцу при входе и изменении (1-002); 14 — выносливость: запас своего персонажа в своём состоянии снимка, 8 бит (1-003); 15 — меч (1-004): фаза удара сущности в снимке (4 бита: фаза 2 + индекс серии 2, маска дельты 5 бит); 16 — ИИ врага (1-007): состояние мозга в снимке (5 бит: архетип 2 + состояние 3, маска дельты 6 бит), удар врага с ИИ решает симуляция — угроза врага только телеграф; 17 — копание инструментом и ярусом (1-010): ответы «нужен инструмент» (11) и «нужен ярус» (12), добыча в такт применённой правки; 18 — строительство (1-011): ответы «обломки» (13) и «нет ресурсов» (14), постановка молотом, стоимость и возврат в сумке; 19 — двери (1-012): запрос «закрыть дверь» (TileOp 4); 20 — время мира в заголовке снимка и дельты (u16, такт суток 0…35 999; 1-014); 21 — сумка ячейками (26: 40 ячеек × предмет и количество), кучи на земле (27), «кучи нет» (28), заявка на сумку (29) (E2-1) 22 — крафт: заявка изготовления (30), ответ (31), очередь изготовления (32) (E2-3); 23 — починка (TileOp 5), ответы «цело» (16), «под ударом» (17), «пауза» (18), заявка на сумку с ячейками открытого сундука (40…69), действие с объектом (33), ответ (34), сундук (35) (E2-5); 24 — сундуки рядом (36): сводка для окна крафта, ингредиенты из сумки и сундуков в 6 тайлах (E2-10); 25 — постройки — предметы: запрос постановки несёт ячейку быстрой панели (TileRequest 19 байт), постановка без молота — предметом из руки (E2-11); 26 — стена в полтайла: запрос правки несёт четверти начала и конца линии (TileRequest 20 байт), маска ячеек в записи постройки (старшие 4 бита байта пола) (E2-12); 27 — запись постройки 9 байт (байт слоёв: ячейки пола, сдвиг мебели) в чанке, пачке и правке тайла; пол и мебель по ячейкам 0,5 (E2-15); 28 — поворот мебели и двери в битах 10–11 объекта заявки, многоклеточная мебель (флаг записи Wide), постановка из меню с изготовлением на месте (бит 4 четвертей заявки), ответ «нужен станок» (20) (E2-16); 29 — изготовление сразу в ячейку сумки: операция 3 и байт ячейки в заявке изготовления (30, 6 байт), ответ «некуда» (12) у изготовления, ответ «сумка полна» (21) у постановки из меню (C-013); 30 — урон (37) игрокам рядом с жертвой: жертва, атакующий, урон u16, тип, флаг «сильный»; в «смерти» (24) — тактов до возрождения и флаг «у кровати» (E3-1); 31 — снаряды (E3-2): «снаряд» (38) — выстрел и конец полёта событиями канала 2, полёт клиент считает сам; лук — бит удара кадра с луком в руках; попадание стрелой — то же «урон» (37); 32 — воткнувшиеся стрелы (C-031): у кучи в «кучах» (27) вид 1 и ось u16 (запись 18 байт); 33 — кровать двуспальная 2 × 2 тайла при любом повороте (C-030): размер мебели — правило и у клиента (предсказание, ObjectUse), сообщения не менялись. 34 — взмах кирки (C-028): «взмах» (39) — удары по тайлам (тайл, объект, удары из нужных, «снят»), копание киркой природного — взмахами по 24 кадра; 35 — снаряжение (E3-6): надетое (предмет в ячейках «голова» / «тело» / «ноги», 3 байта) в конце «сумки» (26).

        /// <summary>
        /// Версия сборки, которую сверяет вход (2.10: «клиент и сервер разных сборок не соединяются»). Пока номера
        /// сборки из CI нет — 0.0.<see cref="ProtocolVersion"/>.
        /// </summary>
        public static readonly NetVersion Version = new NetVersion(0, 0, ProtocolVersion);
    }
}
